// Simple endless runner based on IDEA.md
// Canvas element with id "game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = (canvas.width = canvas.offsetWidth);
  const H = (canvas.height = canvas.offsetHeight);

  // --- player ---
  const player = {
    x: 50,
    y: H / 2 - 15,
    w: 30,
    h: 30,
    dy: 0,
    speed: 4,
    health: 3,
  };

  // --- obstacles & power‑ups ---
  const obstacles = [];
  const powerUps = [];
  let frame = 0;
  let score = 0;
  let gameOver = false;

  // input handling
  const keys = {};
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));

  function spawnObstacle() {
    const size = 20 + Math.random() * 30;
    obstacles.push({
      x: W,
      y: Math.random() * (H - size),
      w: size,
      h: size,
      speed: 3 + Math.random() * 2,
    });
  }

  function spawnPowerUp() {
    const size = 15;
    powerUps.push({
      x: W,
      y: Math.random() * (H - size),
      w: size,
      h: size,
      speed: 3,
    });
  }

  function rectCollide(a, b) {
    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
  }

  function update() {
    if (gameOver) return;
    // player movement
    if (keys['ArrowUp'] || keys['w']) player.dy = -player.speed;
    else if (keys['ArrowDown'] || keys['s']) player.dy = player.speed;
    else player.dy = 0;
    player.y = Math.max(0, Math.min(H - player.h, player.y + player.dy));

    // spawn logic
    if (frame % 90 === 0) spawnObstacle();
    if (frame % 300 === 0) spawnPowerUp();

    // update obstacles
    obstacles.forEach(o => (o.x -= o.speed));
    powerUps.forEach(p => (p.x -= p.speed));

    // collision check
    obstacles.forEach((o, i) => {
      if (rectCollide(player, o)) {
        player.health--;
        obstacles.splice(i, 1);
        if (player.health <= 0) gameOver = true;
      } else if (o.x + o.w < 0) {
        obstacles.splice(i, 1);
        score += 10;
      }
    });
    powerUps.forEach((p, i) => {
      if (rectCollide(player, p)) {
        player.health = Math.min(3, player.health + 1);
        powerUps.splice(i, 1);
        score += 5;
      } else if (p.x + p.w < 0) {
        powerUps.splice(i, 1);
      }
    });

    frame++;
  }

  function draw() {
    // background
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);
    // stars (simple static noise)
    ctx.fillStyle = '#222';
    for (let i = 0; i < 50; i++) {
      const sx = Math.random() * W;
      const sy = Math.random() * H;
      ctx.fillRect(sx, sy, 1, 1);
    }
    // player
    ctx.fillStyle = '#0ff'; // neon cyan
    ctx.fillRect(player.x, player.y, player.w, player.h);
    // obstacles
    ctx.fillStyle = '#f55';
    obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
    // power‑ups
    ctx.fillStyle = '#5f5';
    powerUps.forEach(p => ctx.fillRect(p.x, p.y, p.w, p.h));
    // UI
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    ctx.fillText('Health: ' + player.health, 10, 40);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#f88';
      ctx.textAlign = 'center';
      ctx.font = '32px sans-serif';
      ctx.fillText('Game Over', W / 2, H / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // start
  requestAnimationFrame(loop);
})();
